use vstd::prelude::*;

verus! {

fn concatenate(a: Vec<f32>, b: Vec<f32>) -> (c: Vec<f32>)
    ensures
        c@.len() == a@.len() + b@.len(),
        forall|i: int| 0 <= i < a@.len() ==> c@[i] == a@[i],
        forall|j: int| 0 <= j < b@.len() ==> c@[a@.len() + j] == b@[j],
{
    let a0 = a; // keep names stable for specs
    let b0 = b;

    let mut c: Vec<f32> = Vec::new();

    // Push all elements of a0
    let mut i: usize = 0;
    while i < a0.len()
        invariant
            c@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> c@[k] == a0@[k],
        decreases a0.len() - i,
    {
        c.push(a0[i]);
        i += 1;
    }

    // Push all elements of b0
    let mut j: usize = 0;
    while j < b0.len()
        invariant
            c@.len() == a0@.len() + j as int,
            // a-part preserved
            forall|k: int| 0 <= k < a0@.len() ==> c@[k] == a0@[k],
            // b-part built so far
            forall|k: int| 0 <= k < j as int ==> c@[a0@.len() + k] == b0@[k],
        decreases b0.len() - j,
    {
        c.push(b0[j]);
        j += 1;
    }

    c
}

} // verus!

